// BLOCK 1 — "Fields -> dashboard data".
// A data-mapping / pipeline beat: an Apify output table on the LEFT feeds a BI
// dashboard on the RIGHT. As each source column highlights, a connector draws
// across the gap and the corresponding dashboard tile appears; at the payoff the
// empty dashboard populates with data (bars grow, numbers count up).
// Transparent root (alpha overlay). Everything sized off base/width/height.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { springIn, drawPath, ambientDrift } from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};
const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_MONO = "monospace";

const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const cubic = (t: number, a: number, b: number, c: number, d: number) => {
  const mt = 1 - t;
  return mt * mt * mt * a + 3 * mt * mt * t * b + 3 * mt * t * t * c + t * t * t * d;
};

// column label + its exact beat cue frame (index maps 1:1 to a dashboard tile)
const COLS = [
  { label: "Location", cue: 0 },
  { label: "Zone", cue: 0 },
  { label: "Rating", cue: 92 },
  { label: "Comp.", cue: 115 },
  { label: "Price", cue: 146 },
  { label: "Index", cue: 152 },
  { label: "Date", cue: 158 },
];

const PAYOFF = 222;

const Block1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // ---- Layout (page coords) -------------------------------------------------
  const margin = width * 0.045;
  const panelW = width * 0.36;
  const panelH = height * 0.64;
  const panelY = (height - panelH) / 2;
  const leftX = margin;
  const leftRight = leftX + panelW;
  const rightRight = width - margin;
  const rightX = rightRight - panelW;

  const pad = base * 0.028;
  const radius = base * 0.016;
  const cardShadow = "none";

  // ---- Source table geometry ------------------------------------------------
  const srcTitleH = base * 0.05;
  const tableTopRel = pad + srcTitleH + base * 0.02;
  const headerH = base * 0.05;
  const colGap = base * 0.008;
  const tableW = panelW - pad * 2;
  const colW = (tableW - colGap * (COLS.length - 1)) / COLS.length;
  const rows = 5;
  const rowH = base * 0.05;
  const rowGap = base * 0.016;
  const rowsTopRel = tableTopRel + headerH + base * 0.016;

  const colXPage = (i: number) => leftX + pad + i * (colW + colGap);
  const headerCenterYPage = panelY + tableTopRel + headerH / 2;

  // ---- Dashboard geometry ---------------------------------------------------
  const dTitleH = base * 0.05;
  const dContentX = rightX + pad;
  const dContentY = panelY + pad + dTitleH + base * 0.02;
  const dContentW = panelW - pad * 2;
  const dContentH = panelY + panelH - pad - dContentY;
  const gap = base * 0.016;
  const availH = dContentH - gap * 2;
  const kpiH = availH * 0.26;
  const chartH = availH * 0.42;
  const botH = availH * 0.32;
  const kpiY = dContentY;
  const chartY = kpiY + kpiH + gap;
  const botY = chartY + chartH + gap;
  const tileW = (dContentW - gap * 2) / 3;

  // tile slots in page coords, one per column (index-aligned to COLS)
  const slots = [
    { x: dContentX, y: kpiY, w: tileW, h: kpiH, kind: "kpi" },
    { x: dContentX + tileW + gap, y: kpiY, w: tileW, h: kpiH, kind: "kpi" },
    { x: dContentX + (tileW + gap) * 2, y: kpiY, w: tileW, h: kpiH, kind: "kpi" },
    { x: dContentX, y: chartY, w: dContentW, h: chartH, kind: "bars" },
    { x: dContentX, y: botY, w: tileW, h: botH, kind: "donut" },
    { x: dContentX + tileW + gap, y: botY, w: tileW, h: botH, kind: "line" },
    { x: dContentX + (tileW + gap) * 2, y: botY, w: tileW, h: botH, kind: "minibars" },
  ] as const;

  // dashboard ingest ports: evenly spaced down the left border
  const portY = (i: number) => dContentY + ((i + 0.5) / COLS.length) * dContentH;

  // ---- Entrances ------------------------------------------------------------
  const srcIn = springIn(frame, vfps, 0, "LIQUID");
  const dashIn = springIn(frame, vfps, 0, "LIQUID");
  const srcDrift = ambientDrift(frame, 2, 130, "src");
  const dashDrift = ambientDrift(frame, 2, 150, "dash");
  const srcTransform = `translateY(${interpolate(srcIn, [0, 1], [42, 0]) + srcDrift}px) scale(${interpolate(srcIn, [0, 1], [0.96, 1])})`;
  const dashTransform = `translateY(${interpolate(dashIn, [0, 1], [42, 0]) + dashDrift}px) scale(${interpolate(dashIn, [0, 1], [0.96, 1])})`;

  // ---- Apify chip pulse (f198) ---------------------------------------------
  const chipPulse = interpolate(frame, [198, 208, 222, 236], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // ---- Payoff (f222) --------------------------------------------------------
  const popIn = springIn(frame, vfps, PAYOFF, "LIQUID");

  const cardBase: React.CSSProperties = {
    position: "absolute",
    background: COLORS.card,
    border: `1px solid ${COLORS.border}`,
    borderRadius: radius,
    boxShadow: cardShadow,
  };

  // helper: tiny data-like label
  const monoLabel = (txt: string, size: number, color: string): React.CSSProperties => ({
    fontFamily: FONT_MONO,
    fontSize: size,
    letterSpacing: "0.08em",
    color,
    textTransform: "uppercase",
  });

  // KPI values (index -> tile)
  const kpiVals = [
    { value: 1284, decimals: 0, unit: "", cap: "Records" },
    { value: 37, decimals: 0, unit: "", cap: "Districts" },
    { value: 4.7, decimals: 1, unit: "", cap: "Avg score" },
  ];
  const barFracs = [0.42, 0.6, 0.5, 0.78, 0.55, 0.9, 0.66, 0.82];

  return (
    <AbsoluteFill>
      {/* =============================== SOURCE PANEL =============================== */}
      <div
        style={{
          ...cardBase,
          left: leftX,
          top: panelY,
          width: panelW,
          height: panelH,
          opacity: srcIn,
          transform: srcTransform,
          overflow: "hidden",
        }}
      >
        {/* title bar */}
        <div
          style={{
            position: "absolute",
            left: pad,
            top: pad,
            right: pad,
            height: srcTitleH,
            display: "flex",
            alignItems: "center",
            gap: base * 0.014,
          }}
        >
          {/* Apify chip */}
          <div
            style={{
              width: srcTitleH,
              height: srcTitleH,
              borderRadius: base * 0.01,
              background: "#ffffff",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: srcTitleH * 0.16,
              transform: `scale(${1 + chipPulse * 0.14})`,
              boxShadow: chipPulse > 0.01 ? `0 0 ${base * 0.03 * chipPulse}px ${base * 0.012 * chipPulse}px ${COLORS.orange}` : "none",
              border: `${Math.max(1, base * 0.002 * chipPulse)}px solid rgba(248,102,6,${0.9 * chipPulse})`,
            }}
          >
            <Img
              src={staticFile("assets/apify/Apify symbol colors.svg")}
              style={{ width: "100%", height: "100%", objectFit: "contain" }}
            />
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: base * 0.006 }}>
            <div style={{ ...monoLabel("APIFY OUTPUT", base * 0.014, COLORS.textMuted) }}>APIFY OUTPUT</div>
            <div style={{ width: base * 0.14, height: base * 0.007, background: "rgba(255,255,255,0.1)", borderRadius: 3 }} />
          </div>
          <div style={{ flex: 1 }} />
          <div style={{ ...monoLabel("dataset.json", base * 0.012, COLORS.textSubtle), fontFamily: FONT_MONO, textTransform: "none" as const }}>dataset.json</div>
        </div>

        {/* columns */}
        {COLS.map((c, i) => {
          const hp = springIn(frame, vfps, c.cue, "SNAPPY");
          const hot = hp > 0.35;
          return (
            <div
              key={c.label}
              style={{
                position: "absolute",
                left: pad + i * (colW + colGap),
                top: tableTopRel,
                width: colW,
                height: rowsTopRel - tableTopRel + rows * rowH + (rows - 1) * rowGap,
              }}
            >
              {/* header cell */}
              <div
                style={{
                  position: "relative",
                  height: headerH,
                  borderRadius: base * 0.006,
                  background: "rgba(255,255,255,0.04)",
                  border: `1px solid ${hot ? COLORS.orange : "transparent"}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  overflow: "hidden",
                }}
              >
                <div style={{ position: "absolute", inset: 0, background: COLORS.orangeTint, opacity: clamp01(hp), borderRadius: base * 0.006 }} />
                <span style={{ position: "absolute", ...monoLabel(c.label, base * 0.0135, COLORS.textMuted), opacity: 1 - clamp01(hp) }}>{c.label}</span>
                <span style={{ position: "absolute", ...monoLabel(c.label, base * 0.0135, COLORS.orange), opacity: clamp01(hp), fontWeight: 700 }}>{c.label}</span>
              </div>
              {/* data cells */}
              {Array.from({ length: rows }).map((_, r) => {
                const w = 38 + ((i * 7 + r * 13) % 46);
                return (
                  <div
                    key={r}
                    style={{
                      position: "absolute",
                      left: 0,
                      top: rowsTopRel - tableTopRel + r * (rowH + rowGap),
                      width: colW,
                      height: rowH,
                      borderRadius: base * 0.006,
                      background: "rgba(255,255,255,0.03)",
                      display: "flex",
                      alignItems: "center",
                      padding: `0 ${base * 0.01}px`,
                    }}
                  >
                    <div style={{ position: "relative", width: `${w}%`, height: base * 0.01, borderRadius: base * 0.005 }}>
                      <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.005, background: "rgba(255,255,255,0.16)" }} />
                      <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.005, background: COLORS.orange, opacity: clamp01(hp) }} />
                    </div>
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>

      {/* =============================== DASHBOARD PANEL =============================== */}
      <div
        style={{
          ...cardBase,
          left: rightX,
          top: panelY,
          width: panelW,
          height: panelH,
          opacity: dashIn,
          transform: dashTransform,
          overflow: "hidden",
        }}
      >
        {/* dashboard title bar */}
        <div
          style={{
            position: "absolute",
            left: pad,
            top: pad,
            right: pad,
            height: dTitleH,
            display: "flex",
            alignItems: "center",
            gap: base * 0.014,
          }}
        >
          <div style={{ width: base * 0.024, height: base * 0.024, borderRadius: base * 0.005, background: COLORS.orange }} />
          <div style={{ ...monoLabel("BI DASHBOARD", base * 0.014, COLORS.textMuted) }}>BI DASHBOARD</div>
          <div style={{ flex: 1 }} />
          {[0, 1, 2].map((k) => (
            <div key={k} style={{ width: base * 0.045, height: base * 0.02, borderRadius: base * 0.005, background: "rgba(255,255,255,0.06)" }} />
          ))}
        </div>

        {/* placeholder slots (visible until their tile arrives) */}
        {slots.map((s, i) => {
          const arrive = clamp01((frame - COLS[i].cue) * 0.2);
          const phOp = (1 - arrive) * 0.7;
          if (phOp < 0.02) return null;
          return (
            <div
              key={`ph-${i}`}
              style={{
                position: "absolute",
                left: s.x - rightX,
                top: s.y - panelY,
                width: s.w,
                height: s.h,
                borderRadius: base * 0.01,
                border: `1px dashed rgba(255,255,255,0.08)`,
                background: "rgba(255,255,255,0.015)",
                opacity: phOp,
              }}
            />
          );
        })}

        {/* tiles */}
        {slots.map((s, i) => {
          const cue = COLS[i].cue;
          const cin = springIn(frame, vfps, cue, "SNAPPY");
          if (cin < 0.001) return null;
          const tform = `translateY(${interpolate(cin, [0, 1], [24, 0])}px) scale(${interpolate(cin, [0, 1], [0.9, 1])})`;
          const inner = base * 0.018;
          return (
            <div
              key={`tile-${i}`}
              style={{
                position: "absolute",
                left: s.x - rightX,
                top: s.y - panelY,
                width: s.w,
                height: s.h,
                borderRadius: base * 0.01,
                background: "rgba(255,255,255,0.035)",
                border: `1px solid ${COLORS.border}`,
                opacity: cin,
                transform: tform,
                padding: inner,
                boxSizing: "border-box",
                overflow: "hidden",
              }}
            >
              {/* --- KPI tile --- */}
              {s.kind === "kpi" && (() => {
                const v = kpiVals[i];
                const disp = v.decimals ? (popIn * v.value).toFixed(v.decimals) : Math.round(popIn * v.value).toLocaleString("en-US");
                return (
                  <div style={{ display: "flex", flexDirection: "column", height: "100%", justifyContent: "space-between" }}>
                    <div style={{ ...monoLabel(COLS[i].label, base * 0.012, COLORS.textSubtle) }}>{COLS[i].label}</div>
                    <div style={{ display: "flex", alignItems: "baseline", gap: base * 0.006 }}>
                      <span style={{ fontFamily: FONT_MARKETING, fontWeight: 700, fontSize: base * 0.052, color: COLORS.text, letterSpacing: "-0.03em", lineHeight: 1, fontVariantNumeric: "tabular-nums", opacity: 0.35 + 0.65 * popIn }}>{disp}</span>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: base * 0.006, opacity: popIn }}>
                      <div style={{ width: 0, height: 0, borderLeft: `${base * 0.005}px solid transparent`, borderRight: `${base * 0.005}px solid transparent`, borderBottom: `${base * 0.008}px solid ${COLORS.orange}` }} />
                      <div style={{ ...monoLabel(v.cap, base * 0.011, COLORS.textMuted), textTransform: "none" as const }}>{v.cap}</div>
                    </div>
                  </div>
                );
              })()}

              {/* --- Bar chart tile (Comp.) --- */}
              {s.kind === "bars" && (
                <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
                  <div style={{ ...monoLabel(COLS[i].label + " by district", base * 0.012, COLORS.textSubtle), textTransform: "none" as const, marginBottom: base * 0.01 }}>{COLS[i].label} · by district</div>
                  <div style={{ position: "relative", flex: 1, display: "flex", alignItems: "flex-end", gap: base * 0.01, borderBottom: `1px solid ${COLORS.border}`, paddingBottom: 1 }}>
                    {barFracs.map((f, bi) => {
                      const bp = springIn(frame, vfps, PAYOFF + bi * 3, "SNAPPY");
                      const isMax = f >= 0.9;
                      return (
                        <div
                          key={bi}
                          style={{
                            flex: 1,
                            height: `${f * 92 * bp}%`,
                            borderRadius: `${base * 0.004}px ${base * 0.004}px 0 0`,
                            background: isMax ? COLORS.orange : "rgba(255,255,255,0.18)",
                            boxShadow: isMax ? `0 0 ${base * 0.01}px ${COLORS.orangeTint}` : "none",
                          }}
                        />
                      );
                    })}
                  </div>
                </div>
              )}

              {/* --- Donut tile (Price) --- */}
              {s.kind === "donut" && (() => {
                const R = 32;
                const C = 2 * Math.PI * R;
                const target = 0.68;
                const off = C * (1 - target * popIn);
                const pct = Math.round(target * popIn * 100);
                return (
                  <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
                    <div style={{ ...monoLabel(COLS[i].label, base * 0.012, COLORS.textSubtle) }}>{COLS[i].label}</div>
                    <div style={{ flex: 1, position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      <svg viewBox="0 0 100 100" style={{ width: "70%", height: "70%", transform: "rotate(-90deg)" }}>
                        <circle cx="50" cy="50" r={R} fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth={10} />
                        <circle cx="50" cy="50" r={R} fill="none" stroke={COLORS.orange} strokeWidth={10} strokeLinecap="round" strokeDasharray={C} strokeDashoffset={off} />
                      </svg>
                      <div style={{ position: "absolute", fontFamily: FONT_MARKETING, fontWeight: 700, fontSize: base * 0.022, color: COLORS.text, fontVariantNumeric: "tabular-nums", opacity: popIn }}>{pct}%</div>
                    </div>
                  </div>
                );
              })()}

              {/* --- Sparkline tile (Index) --- */}
              {s.kind === "line" && (() => {
                const pts = [8, 30, 22, 44, 34, 58, 48, 70, 62, 82];
                const n = pts.length;
                const d = pts
                  .map((p, pi) => `${pi === 0 ? "M" : "L"} ${(pi / (n - 1)) * 96 + 2} ${52 - (p / 90) * 44}`)
                  .join(" ");
                const dp = drawPath(frame, vfps, 260, { delay: PAYOFF, preset: "LIQUID" });
                const endX = 96 + 2;
                const endY = 52 - (pts[n - 1] / 90) * 44;
                return (
                  <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
                    <div style={{ ...monoLabel(COLS[i].label, base * 0.012, COLORS.textSubtle) }}>{COLS[i].label}</div>
                    <div style={{ flex: 1, position: "relative" }}>
                      <svg viewBox="0 0 100 56" preserveAspectRatio="none" style={{ width: "100%", height: "100%" }}>
                        <line x1="0" y1="52" x2="100" y2="52" stroke={COLORS.border} strokeWidth={0.6} />
                        <path d={d} fill="none" stroke={COLORS.orange} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={dp.strokeDasharray} strokeDashoffset={dp.strokeDashoffset} opacity={dp.opacity} />
                        {dp.opacity > 0.9 && <circle cx={endX} cy={endY} r={2.6} fill={COLORS.orange} />}
                      </svg>
                    </div>
                  </div>
                );
              })()}

              {/* --- Mini bars tile (Date) --- */}
              {s.kind === "minibars" && (
                <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
                  <div style={{ ...monoLabel(COLS[i].label, base * 0.012, COLORS.textSubtle) }}>{COLS[i].label}</div>
                  <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: base * 0.006, paddingTop: base * 0.008 }}>
                    {[0.5, 0.72, 0.4, 0.88, 0.6, 0.34, 0.78].map((f, mi) => {
                      const mp = springIn(frame, vfps, PAYOFF + mi * 2, "SNAPPY");
                      return (
                        <div key={mi} style={{ flex: 1, height: `${f * 90 * mp}%`, borderRadius: base * 0.003, background: mi === 3 ? COLORS.orange : "rgba(255,255,255,0.16)" }} />
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* =============================== CONNECTORS (overlay) =============================== */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
      >
        {COLS.map((c, i) => {
          const p0x = colXPage(i) + colW;
          const p0y = headerCenterYPage;
          const p3x = rightX;
          const p3y = portY(i);
          const dx = p3x - p0x;
          // Gentle S: hold the header height, then ease down into the port's own
          // lane over a wide arc and run nearly flat into it. A wider, later
          // descent stops all seven curves diving through one steep "neck".
          const p1x = p0x + dx * 0.5;
          const p1y = p0y;
          const p2x = p3x - dx * 0.16;
          const p2y = p3y;
          const len = Math.hypot(dx, p3y - p0y) * 1.25;
          const dp = drawPath(frame, vfps, len, { delay: c.cue, preset: "LIQUID" });
          const path = `M ${p0x} ${p0y} C ${p1x} ${p1y} ${p2x} ${p2y} ${p3x} ${p3y}`;

          // travelling flow pulse just after the connector draws
          const pulseStart = c.cue + 16;
          const pt = clamp01((frame - pulseStart) / 24);
          const pulseOn = frame >= pulseStart && pt < 1;
          const px = cubic(pt, p0x, p1x, p2x, p3x);
          const py = cubic(pt, p0y, p1y, p2y, p3y);

          // Once a field is "delivered" (its pulse has reached the dashboard) the
          // connector recedes to a faint residual pipe. Only the field currently
          // being mapped reads as bright, so the bundle stays calm rather than
          // showing seven full-strength lines crossing at once.
          const deliver = c.cue + 42;
          const active = interpolate(
            frame,
            [c.cue, c.cue + 14, deliver, deliver + 30],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const RESIDUAL = 0.16;
          const lineOp = dp.opacity * (RESIDUAL + (0.82 - RESIDUAL) * active);
          const endOp = dp.opacity * (0.45 + 0.55 * active);

          const nub = base * 0.02;
          return (
            <g key={c.label}>
              <path
                d={path}
                fill="none"
                stroke={COLORS.orange}
                strokeWidth={base * (0.0015 + 0.0012 * active)}
                strokeLinecap="round"
                strokeDasharray={dp.strokeDasharray}
                strokeDashoffset={dp.strokeDashoffset}
                opacity={lineOp}
              />
              {/* source tap dot */}
              <circle cx={p0x} cy={p0y} r={base * 0.0045} fill={COLORS.orange} opacity={endOp} />
              {/* dashboard ingest port + nub */}
              <line x1={p3x} y1={p3y} x2={p3x + nub} y2={p3y} stroke={COLORS.orange} strokeWidth={base * 0.0022} strokeLinecap="round" opacity={endOp} />
              <circle cx={p3x} cy={p3y} r={base * 0.006} fill={COLORS.card} stroke={COLORS.orange} strokeWidth={base * 0.002} opacity={endOp} />
              {pulseOn && (
                <circle cx={px} cy={py} r={base * 0.0075} fill={COLORS.orange} style={{ filter: "none" }} opacity={interpolate(pt, [0, 0.1, 0.85, 1], [0, 1, 1, 0])}>
                </circle>
              )}
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export const fps = 25;
export const durationInFrames = 300;
export default Block1;
